+  Widget build(BuildContext context) => Card(
+    child: Padding(
+      padding: const EdgeInsets.all(28),
+      child: Column(
+        children: [
+          Icon(icon, size: 42),
+          const SizedBox(height: 8),
+          Text(text, textAlign: TextAlign.center),
+          if (action != null)
+            TextButton(
+              onPressed: action,
+              child: const Text('Tentar novamente'),
+            ),
+        ],
+      ),
+    ),
+  );
+}
