         return false;
       return true;
     }).toList();
     result.sort((a, b) {
       final compare = a.meetings.first.start.compareTo(b.meetings.first.start);
       return compare == 0 ? a.title.compareTo(b.title) : compare;
     });
     _json(request, 200, result.map(_activityJson).toList());
   }
 
