         'titulo': 'Alvo',
         'tipo': 'palestra',
         'salaId': 'sala-101',
         'vagas': vagas,
         'encontros': [
           {
             'inicio': '${dia}T$inicio:00-03:00',
             'fim': '${dia}T$fim:00-03:00'
           }
         ]
       });
   return criada.json['id'] as String;
