+            if (inscricao.status == 'convocada' &&
+                inscricao.convocadaAte != null)
+              _convocacaoPrazo(inscricao),
+            if (!organization &&
+                (inscricao.status == 'confirmada' ||
+                    inscricao.status == 'em_espera'))
+              Align(
