  void initState() { super.initState(); _load(); }

  void _restartCountdown() {
    _countdown?.cancel();
    if (_hasConvocada) {
      _clock = DateTime.now();
      _countdown = Timer.periodic(const Duration(seconds: 1), (_) {
        setState(() { _clock = _clock.add(const Duration(seconds: 1)); });
      });
    }
  }

  bool get _organization => currentUser.role == 'organizacao';
  AppUser get currentUser => ApiClient.knownUsers.firstWhere((u) => u.id == selectedUser);

  Future<void> _load() async {
    _countdown?.cancel();
    setState(() { loading = true; error = null; });
    widget.client.user = selectedUser;
    try {
      final results = await Future.wait([
        widget.client.activities(),
