      ]);
      atividades = results[0];
      inscricoes = results[1];
    } on ApiFailure catch (e) {
      error = e.code;
    } catch (_) {
      error = 'Não foi possível conectar à API';
    }
    if (!mounted) return;
    setState(() { loading = false; });
    if (loading == false) ...
  }
}
