   String? _validateCreate(Activity activity) {
     if (activity.type != 'palestra' && activity.type != 'minicurso')
       return 'DADOS_INVALIDOS';
     if ((activity.type == 'palestra' && activity.meetings.length != 1) ||
         (activity.type == 'minicurso' &&
